import { describe, expect, test } from "vitest";
import type { ConfigSnapshot, SettingControl, SettingValue } from "../../../S1/settings-kit";
import { S2_SETTINGS_SECTIONS } from "../../sections";

const snapshot: ConfigSnapshot = {
  folder: null,
  revision: "revision-1",
  entries: [],
};

const EXPECTED_KEYS = [
  "edit.mode",
  "edit.fuzzyMatch",
  "edit.fuzzyThreshold",
  "edit.streamingAbort",
  "edit.recoverInlineEdits",
  "edit.blockAutoGenerated",
  "edit.enforceSeenLines",
  "edit.blackbox.enabled",
  "edit.autoRepair.enabled",
  "readLineNumbers",
  "read.defaultLimit",
  "read.renderMarkdown",
  "read.toolResultPreview",
  "read.summarize.enabled",
  "read.summarize.prose",
  "read.summarize.minBodyLines",
  "read.summarize.minCommentLines",
  "read.summarize.minTotalLines",
  "read.summarize.unfoldUntil",
  "read.summarize.unfoldLimit",
  "lsp.enabled",
  "lsp.lazy",
  "lsp.shared",
  "lsp.formatOnWrite",
  "lsp.diagnosticsOnWrite",
  "lsp.diagnosticsOnEdit",
  "lsp.diagnosticsDeduplicate",
  "lsp.requestTimeout",
  "bash.enabled",
  "bash.allowCompoundCommands",
  "bash.autoBackground.enabled",
  "bash.gitGuard",
  "bash.patterns",
  "bashInterceptor.enabled",
  "bash.direnv",
  "bash.direnvLoadTimeoutMs",
  "shellMinimizer.enabled",
  "shellMinimizer.sourceOutlineLevel",
  "eval.py",
  "eval.js",
  "eval.autoProvision",
  "eval.tools.enabled",
  "eval.workpool.freshAgents",
  "eval.autoBackground.enabled",
  "python.kernelMode",
  "python.interpreter",
] as const;

function allControls(): SettingControl[] {
  return S2_SETTINGS_SECTIONS.flatMap((descriptor) => [...descriptor.controls]);
}

function control(key: string): SettingControl {
  const found = allControls().find((candidate) => candidate.key === key);
  if (!found) throw new Error(`Missing descriptor control ${key}`);
  return found;
}

function validate(key: string, value: SettingValue) {
  return control(key).validate(value, snapshot);
}

describe("S2 Files and Shell sections", () => {
  test("covers exactly the six S5 groups with the v18.12.6 registered keys", () => {
    expect(S2_SETTINGS_SECTIONS).toHaveLength(6);
    expect(S2_SETTINGS_SECTIONS.map((descriptor) => descriptor.inventory)).toEqual([
      ["S5.files-editing"],
      ["S5.files-reading"],
      ["S5.files-read-summaries"],
      ["S5.files-lsp"],
      ["S5.shell-bash"],
      ["S5.shell-eval-runtimes"],
    ]);
    expect(
      allControls()
        .map((descriptor) => descriptor.key)
        .sort(),
    ).toEqual([...EXPECTED_KEYS].sort());
    expect(S2_SETTINGS_SECTIONS.map((descriptor) => descriptor.requires)).toEqual(
      S2_SETTINGS_SECTIONS.map(() => ["host.config"]),
    );
  });

  test("describes shared language servers as omp 18.12.6 starts them: one server per connection, kept warm for the next", () => {
    const description = control("lsp.shared").description ?? "";
    expect(description).toContain("its own server");
    expect(description).toContain("stays warm");
    expect(description).not.toContain("Share one language server");
  });

  test("describes every Files setting and keeps terminal-only previews read-only", () => {
    for (const key of EXPECTED_KEYS.slice(0, 20)) {
      expect(control(key).description?.trim(), key).toBeTruthy();
    }
    expect(control("read.toolResultPreview").readOnly?.reason).toBe(
      "This preference only changes omp's terminal; the app does not use it.",
    );
  });

  test("validates registered booleans, enums, numbers, lists and paths", () => {
    expect(validate("edit.fuzzyMatch", { secret: false, value: true })).toEqual({ valid: true });
    expect(validate("edit.fuzzyMatch", { secret: false, value: "true" })).toMatchObject({
      valid: false,
      code: "boolean",
    });
    expect(validate("edit.mode", { secret: false, value: "hashline" })).toEqual({ valid: true });
    expect(validate("edit.mode", { secret: false, value: "unknown" })).toMatchObject({
      valid: false,
      code: "enum",
    });
    expect(validate("edit.fuzzyThreshold", { secret: false, value: 0.95 })).toEqual({
      valid: true,
    });
    expect(validate("edit.fuzzyThreshold", { secret: false, value: 1.1 })).toMatchObject({
      valid: false,
      code: "range",
    });
    expect(validate("read.defaultLimit", { secret: false, value: 300 })).toEqual({ valid: true });
    expect(validate("read.defaultLimit", { secret: false, value: -1 })).toMatchObject({
      valid: false,
      code: "range",
    });
    expect(validate("lsp.requestTimeout", { secret: false, value: 0 })).toEqual({ valid: true });
    expect(validate("lsp.requestTimeout", { secret: false, value: 3600 })).toEqual({
      valid: true,
    });
    expect(validate("lsp.requestTimeout", { secret: false, value: -1 })).toMatchObject({
      valid: false,
      code: "range",
    });
    expect(validate("lsp.requestTimeout", { secret: false, value: 3600.1 })).toMatchObject({
      valid: false,
      code: "range",
    });
    // 3601 is a whole number one above the maximum: 3600.1 alone fails on being fractional, whatever the maximum is.
    expect(validate("lsp.requestTimeout", { secret: false, value: 3601 })).toMatchObject({
      valid: false,
      code: "range",
    });
    expect(validate("bash.patterns", { secret: false, value: [] })).toEqual({ valid: true });
    expect(
      validate("bash.patterns", {
        secret: false,
        value: [{ match: "git push *", approval: "prompt" }],
      }),
    ).toEqual({ valid: true });
    // omp drops rules with an empty match or an approval other than allow/deny/prompt.
    for (const value of [
      "*",
      [{ match: " ", approval: "allow" }],
      [{ match: "ls", approval: "yes" }],
    ]) {
      expect(validate("bash.patterns", { secret: false, value })).toMatchObject({
        valid: false,
        code: "rows",
      });
    }
    expect(validate("python.interpreter", { secret: false, value: "" })).toEqual({ valid: true });
    expect(validate("python.interpreter", { secret: false, value: "\0" })).toMatchObject({
      valid: false,
      code: "path",
    });
  });

  test("describes Git Guard as a live, default-off boolean control", () => {
    const guard = control("bash.gitGuard");
    expect(guard.kind).toBe("boolean");
    expect(guard.apply).toBe("live");
    expect(guard.description).toContain("Block Git commands");
    expect(validate("bash.gitGuard", { secret: false, value: false })).toEqual({ valid: true });
    expect(validate("bash.gitGuard", { secret: false, value: true })).toEqual({ valid: true });
    expect(validate("bash.gitGuard", { secret: false, value: "true" })).toMatchObject({
      valid: false,
      code: "boolean",
    });
    expect(control("eval.js").description).toBe(
      "Allow evaluation code to run JavaScript in omp's own runtime.",
    );
  });

  test("matches v18.9.1 live and reload boundaries", () => {
    for (const key of [
      "readLineNumbers",
      "read.defaultLimit",
      "read.renderMarkdown",
      "read.toolResultPreview",
      "read.summarize.enabled",
      "read.summarize.prose",
      "read.summarize.minBodyLines",
      "read.summarize.minCommentLines",
      "read.summarize.minTotalLines",
      "read.summarize.unfoldUntil",
      "read.summarize.unfoldLimit",
    ]) {
      expect(control(key).apply).toBe("live");
    }

    const upstreamApplyEvidence = [
      ["edit.mode", "live", "edit/settings.ts:36-50; utils/edit-mode.ts:25-27"],
      ["edit.fuzzyMatch", "live", "edit/settings.ts:68-79; edit/index.ts:602-605"],
      ["edit.fuzzyThreshold", "live", "edit/settings.ts:81-104; edit/index.ts:602-605"],
      ["edit.streamingAbort", "live", "edit/settings.ts:106-117; session/stream-guards.ts:75"],
      ["edit.recoverInlineEdits", "live", "edit/settings.ts:118-129; sdk.ts:4395"],
      ["edit.blockAutoGenerated", "live", "edit/settings.ts:130-141; edit/index.ts:605"],
      ["edit.enforceSeenLines", "live", "edit/settings.ts:142-153; edit/index.ts:604"],
      ["edit.blackbox.enabled", "live", "edit/settings.ts:154-165; edit/blackbox.ts:30"],
      ["edit.autoRepair.enabled", "live", "edit/settings.ts:166-178; edit/auto-repair.ts:346"],
      ["lsp.enabled", "live", "lsp/settings.ts:8-18; tools/index.ts:740-742; sdk.ts:5088-5136"],
      ["lsp.lazy", "live", "lsp/settings.ts:20-31; sdk.ts:5077-5086,5130-5135; main.ts:2549-2555"],
      ["lsp.shared", "live", "lsp/settings.ts:33-44; sdk.ts:5064-5075"],
      [
        "lsp.formatOnWrite",
        "live",
        "lsp/settings.ts:46-56; edit/index.ts:172-177; write.ts:501-515",
      ],
      ["lsp.diagnosticsOnWrite", "live", "lsp/settings.ts:58-68; write.ts:501-515"],
      ["lsp.diagnosticsOnEdit", "live", "lsp/settings.ts:70-80; edit/index.ts:172-177"],
      [
        "lsp.diagnosticsDeduplicate",
        "live",
        "lsp/settings.ts:82-92; write.ts:501-515; lsp/deferred-diagnostics.ts:42-45",
      ],
      ["bash.enabled", "live", "exec/settings.ts:82-92; tools/index.ts:740-742"],
      ["bash.allowCompoundCommands", "live", "exec/settings.ts:94-105; tools/bash.ts:504"],
      [
        "bash.autoBackground.enabled",
        "live",
        "exec/settings.ts:107-118; tools/bash.ts:599-600,1139-1147",
      ],
      ["bash.patterns", "live", "exec/settings.ts:133-144; tools/bash.ts:503"],
      ["bashInterceptor.enabled", "live", "exec/settings.ts:147-157; tools/bash.ts:992"],
      ["bash.direnv", "live", "exec/settings.ts:165-177; exec/bash-executor.ts:561-563"],
      [
        "bash.direnvLoadTimeoutMs",
        "live",
        "exec/settings.ts:179-190; exec/bash-executor.ts:561; tools/bash.ts:1217",
      ],
      ["shellMinimizer.enabled", "live", "exec/settings.ts:193-203; exec/bash-executor.ts:542"],
      [
        "shellMinimizer.sourceOutlineLevel",
        "live",
        "exec/settings.ts:229-240; exec/bash-executor.ts:314",
      ],
      ["eval.py", "live", "eval/settings.ts:8-19; tools/eval-backends.ts:3-14"],
      ["eval.js", "live", "eval/settings.ts:21-32; tools/eval-backends.ts:3-14"],
      [
        "eval.autoProvision",
        "live",
        "eval/settings.ts:34-45; tools/eval.ts:398-404; eval/js/executor.ts:139",
      ],
      [
        "eval.tools.enabled",
        "live",
        "eval/settings.ts:46-58; task/eval-tools.ts:14-81; session/agent-session.ts:7229",
      ],
      ["eval.workpool.freshAgents", "live", "eval/settings.ts:59-69; task/workpool.ts:135-143"],
      [
        "eval.autoBackground.enabled",
        "live",
        "eval/settings.ts:71-82; tools/eval.ts:398-404,613-630",
      ],
      [
        "python.kernelMode",
        "live",
        "eval/settings.ts:92-103; eval/py/index.ts:21-35; eval/py/executor.ts:599-603",
      ],
      ["python.interpreter", "live", "eval/settings.ts:105-116; eval/py/index.ts:21-35"],
    ] as const;
    for (const [key, apply, source] of upstreamApplyEvidence) {
      expect(control(key).apply, `${key}: omp v18.9.1 ${source}`).toBe(apply);
    }
  });
});
